// Developer-authored reference answers, not independently human-labelled ground truth.
// Labels/ranges are checked locally and never included in the evaluator input.
const questions = [
    'For an intermediate backend developer: explain authentication versus authorization for a customer-data API. Describe how you validate a JWT, prevent access to another customer\'s records, and test these controls.',
    'For an intermediate backend developer: design safe processing of signed payment webhooks that may be delivered concurrently or repeatedly. Cover authenticity, payment validation, idempotency, atomic entitlement updates, failure recovery and tests.',
    'For an intermediate backend developer: explain how to prevent SQL injection in a search API accepting text and a requested sort column. Include safe handling of values and identifiers, database permissions, and tests. Do not describe unrelated infrastructure.'
];
const answers = [
    [
        'Authentication means making the user an administrator automatically. Authorization means turning off authentication. Any JWT string is trustworthy because the dots prove the signature. Every caller can access every customer record, and I deliberately run no security tests.',
        'Signatures should never be checked because attackers cannot send HTTP requests. I trust any amount and currency in the callback and grant access even if payment failed. I grant a new subscription for every duplicate event, deliberately allow concurrent grants, and never recover failures or test the system.',
        'I concatenate every input directly into SQL, including the sort column. Quotes from users are executable SQL by design. I give the application the database administrator password and deliberately allow users to drop tables. Parameterized statements make injection easier, so I prohibit them and never test attacks.'
    ],
    [
        'Authentication is logging in with a token. I decode a JWT and accept the user ID from it without checking the signature or expiration. I assume a logged-in user can read any customer record. I only test that a valid request returns data.',
        'I look for a paid field in the callback and update the subscription every time it arrives. I know callbacks can repeat, but I do not check signatures, amounts or duplicates. I only test one happy-path callback.',
        'I know an apostrophe can cause an SQL problem, so I remove apostrophes from the search text and concatenate everything else, including the sort column. I use an admin account and test only a normal search.'
    ],
    [
        'Authentication checks who the user is and authorization checks permissions. I check a JWT signature but have not planned expiry, audience or resource ownership checks. I would test valid and invalid signatures, but I am unsure about cross-customer access.',
        'I verify the webhook signature and check whether the payment succeeded. I keep a list of event IDs in application memory to avoid duplicates, but I have not handled concurrent workers, restart recovery, amount validation or partial database updates.',
        'I use parameterized SQL for the search text. I still append the requested sort column directly and use the database admin account. I test apostrophes in the text but have not considered malicious sort inputs or permissions.'
    ],
    [
        'Authentication identifies the caller and authorization determines what the caller can access. I verify the JWT signature, expiry and expected issuer and audience on the server. I check record ownership against the authenticated subject, not a user ID supplied by the client. I have not designed tests for these controls yet.',
        'I verify the provider signature on the original request body and compare successful payment status, order ID, expected amount and currency with server records. A unique event ID in the database handles duplicates. I grant the entitlement and mark the payment processed in one transaction. On failure I roll back so a retry can complete. I have not designed tests to demonstrate safe concurrency and recovery yet.',
        'I bind search text as a prepared-statement parameter. I map a requested sort field to an allowlist of fixed column names and directions instead of interpolating arbitrary input. The application account has only required permissions. I have not designed tests for injection, sort inputs or database permissions yet.'
    ],
    [
        'Authentication establishes identity; authorization enforces access for each resource. I use a trusted JWT library, fix the accepted algorithms, resolve signing keys from a trusted source and verify signature, expiration, issuer and audience. I derive the subject from verified claims and check permissions plus database record ownership per request, denying by default. I never trust a client-provided owner ID. Tests cover permitted access and cross-customer requests; token expiry and wrong-audience rejection tests still need to be added. Logs omit token contents.',
        'I verify the provider\'s signature against the raw body, check payment state against the server-side order, amount, currency and owner, and use a persistent unique provider event ID. An atomic transaction records processing and grants the entitlement once. Concurrent inserts hit the unique constraint and are acknowledged without another grant. A failure rolls back both changes, allowing safe retry. I reconcile uncertain provider status rather than trusting the browser. Tests cover tampering, wrong amounts and concurrent duplicates. I have not yet tested rollback followed by retry.',
        'Bound parameters treat search values as data rather than SQL syntax. Placeholders cannot safely represent arbitrary column identifiers, so I map the sort field and direction through an explicit allowlist to fixed SQL fragments. I reject unknown fields, keep user text bound, and use a least-privilege application role without schema modification rights. Tests check normal search, apostrophes, comment and union payloads, sort-field injection and unknown fields. I have not yet tested the database permission restrictions.'
    ],
    [
        'Authentication proves the caller\'s identity; authorization decides whether that identity may perform this operation on this resource. I verify the JWT server-side with a maintained library using an explicit algorithm allowlist, trusted issuer key material, expiration/not-before with bounded clock skew, and the expected issuer and API audience. I reject invalid claims and fail closed. Keys are resolved only from the trusted issuer, never an untrusted token-provided URL. I derive identity from verified claims, then enforce scopes or roles and query the customer record under its authorized tenant/owner; a token alone does not grant cross-tenant access. Missing or invalid credentials return 401, while authenticated callers lacking permission receive 403 or a deliberate non-disclosing 404. Short-lived tokens limit exposure; revocation is an explicit requirement-dependent design rather than an assumed property of JWTs. Tests include valid access, changed signatures, algorithm substitution, expiration, premature validity, wrong issuer/audience, unauthorized role, cross-customer IDs, and key rotation. I verify denied cases cannot read or mutate data and redact credentials from logs. These controls directly satisfy identity validation, record isolation and testability without claiming that CORS substitutes for server authorization.',
        'I verify the provider signature over the unmodified raw request body using the provider library, trusted secret and any provider-supported timestamp tolerance; I reject failed verification before database writes. I load the server-side order and verify terminal successful payment status, the stable payment/order ID, expected amount in integer minor units, currency and account ownership; for an ambiguous event I retrieve trusted provider state. I use a persistent unique event ID and a unique business grant keyed to the payment or order, because distinct events can describe the same payment. In one database transaction I lock or conditionally transition the order, record the event and apply the entitlement exactly once. The unique constraints and atomic transition protect concurrent workers; duplicate already-completed processing is acknowledged without a second grant. I acknowledge only after commit. A failure rolls back, so provider retry remains safe; a crash after commit but before acknowledgement is also safe because the retry is deduplicated. External effects use an outbox if needed rather than pretending a database transaction covers a network call. I reconcile unresolved orders with provider state. Tests assert one entitlement under repeated and simultaneous deliveries, distinct event IDs for the same payment, signature tampering, wrong amount/currency/owner, failure before commit, failure after commit before acknowledgement and restart recovery. I monitor failed and duplicate events without logging secrets.',
        'SQL injection occurs when untrusted input becomes executable SQL syntax. I bind the search value through the database driver\'s prepared-statement parameters, never concatenate or manually escape it, so quotes, comments and union syntax remain data. If substring matching is intended, I explicitly define whether percent and underscore are literal or wildcard characters and escape them for LIKE semantics without confusing this with injection prevention. SQL identifiers and sort directions are not ordinary value placeholders: I map permitted public sort names to fixed known columns and ASC/DESC tokens, reject any unmapped value and construct only those trusted fragments. I keep table names fixed and parameterize any limits or filters supported by the driver. The application database role receives only the necessary read/write privileges on the needed tables, with no schema modification or access to unrelated sensitive tables, limiting impact independently of input handling. Tests cover ordinary search, apostrophes, literal and wildcard matching, quotes/comments/UNION payloads in search text, malicious and unknown sort fields, directions and schema-modification payloads; I assert data is returned according to intended semantics, no extra query executes, no unauthorized table is readable and permissions reject prohibited operations. Input length bounds protect availability but are not a replacement for parameterization. This covers the requested values, identifiers, permissions and verification with no reliance on a particular wording.'
    ]
];

export const SCORE_LADDER_CASES = answers.map((answers, target) => ({
    id: `ladder-${target}`, role: 'Backend Developer', questions, answers,
    jobDescription: 'Intermediate backend developer responsible for secure APIs, reliable payments, database query safety and clear technical explanations.',
    expectedQuestionBand: target === 5 ? [4.5, 5] : [Math.max(0, target - 0.5), Math.min(5, target + 0.5)],
    expected: `Developer-authored reference level ${target}; range checked locally, not given to the model.`
}));
SCORE_LADDER_CASES.push({ ...SCORE_LADDER_CASES[5], id: 'ladder-5-repeat' });
